#!/usr/bin/env python3
"""Report candidate registry matches for unresolved migration tokens.

Reads `.workspace/.artifacts/.checklists/migration-dryrun.log` for unresolved tokens
and searches `Meta/registry/**` YAML entries for id, udi, slug/name, and udi tail
matches. Writes results to `.workspace/.artifacts/.checklists/token-candidates.log` and
prints a concise summary to stdout.
"""
from __future__ import annotations

import re
from pathlib import Path
import yaml
from typing import Dict, List

ROOT = Path(__file__).resolve().parents[3]
ARTIFACTS = ROOT / '.workspace' / '.artifacts' / '.checklists'
DRYLOG = ARTIFACTS / 'migration-dryrun.log'
OUT = ARTIFACTS / 'token-candidates.log'
REGROOT = ROOT / 'Meta' / 'registry'


def load_tokens() -> List[str]:
    if not DRYLOG.exists():
        return []
    text = DRYLOG.read_text(encoding='utf-8')
    tokens = []
    in_section = False
    for line in text.splitlines():
        if line.strip() == 'Unresolved tokens:':
            in_section = True
            continue
        if in_section:
            s = line.strip()
            if not s:
                continue
            # lines that look like paths should be ignored
            if s.lower().endswith('.yaml'):
                continue
            tokens.append(s)
    return tokens


def scan_registries() -> Dict[str, List[Dict[str, str]]]:
    entries = {}
    if not REGROOT.exists():
        return entries
    for y in REGROOT.rglob('*.yaml'):
        try:
            data = yaml.safe_load(y.read_text(encoding='utf-8'))
        except Exception:
            continue
        if not isinstance(data, dict):
            continue
        udi = data.get('udi')
        idv = data.get('id')
        slug = data.get('slug') or data.get('name')
        key = str(y)
        entries[key] = []
        entries[key].append({'udi': udi or '', 'id': idv or '', 'slug': slug or ''})
    return entries


def find_candidates(tokens, entries):
    candidates = {t: [] for t in tokens}
    for path, infos in entries.items():
        for info in infos:
            udi = info.get('udi','')
            idv = info.get('id','')
            slug = info.get('slug','')
            tail = udi.split('.')[-1] if udi and '.' in udi else ''
            for t in tokens:
                tl = t.lower()
                matched = False
                reasons = []
                if idv and tl == idv.lower():
                    matched = True
                    reasons.append('id')
                if slug and tl == slug.lower():
                    matched = True
                    reasons.append('slug')
                if udi and tl == udi.lower():
                    matched = True
                    reasons.append('udi')
                if tail and tl == tail.lower():
                    matched = True
                    reasons.append('udi_tail')
                if udi and udi.lower().endswith(tl):
                    matched = True
                    reasons.append('udi_endswith')
                if matched:
                    candidates[t].append({'path': path, 'udi': udi, 'id': idv, 'slug': slug, 'reasons': reasons})
    return candidates


def main():
    tokens = load_tokens()
    entries = scan_registries()
    candidates = find_candidates(tokens, entries)
    ARTIFACTS.mkdir(parents=True, exist_ok=True)
    out_lines = []
    for t in tokens:
        out_lines.append(f"Token: {t}")
        cand = candidates.get(t, [])
        if not cand:
            out_lines.append('  No candidates found')
        else:
            for c in cand:
                out_lines.append(f"  - {c['path']} -> udi={c['udi'] or '<none>'}, id={c['id'] or '<none>'}, slug={c['slug'] or '<none>'}, reasons={','.join(c['reasons'])}")
        out_lines.append('')
    OUT.write_text('\n'.join(out_lines), encoding='utf-8')
    print(OUT)


if __name__ == '__main__':
    main()
